    confirmed_dirs: list[Path] = []

    def classify(directory: Path, fd_or_path: Any) -> list[tuple[str, bool, bool]]:
        try:
            entries = list(os.scandir(fd_or_path))
        except OSError as error:
            raise ValueError(
                f"cannot scan directory {directory}: {error}"
            ) from error
        found: list[tuple[str, bool, bool]] = []
        for entry in entries:
            try:
                is_file = entry.is_file(follow_symlinks=False)
                is_dir = (
                    not is_file
                    and recursive
                    and entry.is_dir(follow_symlinks=False)
                )
            except OSError as error:
                raise ValueError(
                    f"cannot inspect entry {directory / entry.name}: {error}"
                ) from error
            found.append((entry.name, is_file, is_dir))
        return found

    def walk(
        directory: Path,
        rel_prefix: str,
        parent_fd: int,
        entries: list[tuple[str, bool, bool]],
    ) -> None:
        for name, is_file, is_dir in entries:
            if is_file:
                if Path(name).suffix.lower() in IMAGE_EXTENSIONS:
                    rel_paths.append(rel_prefix + name)
            elif is_dir:
                subdirectory = directory / name
                # Open the confirmed subdirectory through the pinned
                # parent with O_NOFOLLOW and scan the descriptor itself:
                # a symlink swapped onto the path by now fails the whole
                # import here, and the link target is never scanned.
                try:
