@staticmethod
def _open_real_directory(
    name: str, dir_fd: int | None, path: Path
) -> int:
    """Open a confirmed directory, refusing a symlink swapped onto it.

    The open uses ``O_DIRECTORY | O_NOFOLLOW`` — relative to the pinned
    parent descriptor when ``dir_fd`` is given — so a symbolic link (or
    any non-directory) that replaced the confirmed directory is never
    descended through.  A symlink swap raises the import's "directory
    changed" error naming the replaced path; any other open failure
    propagates as the underlying :class:`OSError`.
